import math, heapq, random, itertools, re, html
from pathlib import Path
from collections import deque, Counter
from decimal import Decimal, localcontext, ROUND_HALF_EVEN
from fractions import Fraction

def database(s):
    lines = s.splitlines()
    a = []
    out = []
    for line in lines[1:]:
        (op, *v) = line.split()
        v = list(map(int, v))
        if op == '+':
            a.insert(v[0], v[1])
        elif op == '-':
            a.pop(v[0])
        elif op == '*':
            a[v[0]] = v[1]
        else:
            out.append(str(a.index(v[0])) if v[0] in a else 'Failed')
    return '\n'.join(out)
import sys
sys.stdout.write(database(sys.stdin.read()) + '\n')

