import sys

def solve(text):
    values = list(map(int, text.split()))
    groups = {}
    answers = [None] * values[0]
    for i, (a, b) in enumerate(zip(values[1::2], values[2::2])):
        groups.setdefault(b, []).append((a, i))
    row = [1]
    for b in range(max(groups, default=0) + 1):
        if b in groups:
            rendered = {}
            for a, i in groups[b]:
                a = min(a, b-a)
                if a not in rendered:
                    rendered[a] = str(row[a])
                answers[i] = rendered[a]
        row = [1] + [row[j-1] + row[j] for j in range(1, len(row))] + [1]
    return '\n'.join(answers) + '\n'

sys.stdout.write(solve(sys.stdin.read()))

