def valid(number, text):
    if not text.endswith("\n") or "\r" in text:
        return False
    lines = text.split("\n")[:-1]
    try:
        head = list(map(int, lines[0].split()))
    except (ValueError, IndexError):
        return False
    if len(head) != 4:
        return False
    n, m, k, b = head
    if not (1 <= n <= 10 and 1 <= m <= 10 and 1 <= k and 0 <= b < n * m) or len(lines) != 1 + k + b:
        return False
    total = n * m - b
    locks, obstacles = [], []
    for line in lines[1:1 + k]:
        v = line.split()
        if len(v) != 3 or not all(x.isdigit() for x in v):
            return False
        r, c, t = map(int, v)
        if not (1 <= r <= n and 1 <= c <= m and 1 <= t <= total):
            return False
        locks.append((r, c, t))
    for line in lines[1 + k:]:
        v = line.split()
        if len(v) != 2 or not all(x.isdigit() for x in v):
            return False
        r, c = map(int, v)
        if not (1 <= r <= n and 1 <= c <= m):
            return False
        obstacles.append((r, c))
    lock_cells = {(r, c) for r, c, _ in locks}
    return (any(t == 1 for *_, t in locks) and len({t for *_, t in locks}) == k and len(lock_cells) == k
            and len(set(obstacles)) == b and not (lock_cells & set(obstacles)))

def valid(text):
    """题面：输入为一个整数 n（1<=n<=10^9）。"""
    return re.fullmatch(r'[1-9][0-9]*\n', text) is not None and 1 <= int(text) <= 10**9

def valid(text):
    """题面契约：第一行 N（1<=N<=100）；接下来 N 行每行 4 个整数 T R B L，0<=颜色<=1000。"""
    if not text.endswith("\n"):
        return False
    lines = text[:-1].split("\n")
    if not lines[0].isdigit() or str(int(lines[0])) != lines[0]:
        return False
    n = int(lines[0])
    if not 1 <= n <= 100 or len(lines) != n + 1:
        return False
    for line in lines[1:]:
        toks = line.split(" ")
        if len(toks) != 4 or any(not t.isdigit() or str(int(t)) != t or int(t) > 1000 for t in toks):
            return False
    return True

