if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('batch',type=int);p.add_argument('oracle');p.add_argument('--submit',action='store_true');a=p.parse_args();run(a.batch,a.oracle,a.submit)

"""缺桶题与大输出题的独立答案算法；不改变题号绑定与输出限制。"""
import math,heapq,random,itertools,re,html
from pathlib import Path
from collections import deque,Counter
from decimal import Decimal,localcontext,ROUND_HALF_EVEN
from fractions import Fraction
NUMBERS=[19965,19967,19971,19974,19984,19998,27699]
def luffy(s):
 a,b,c=map(int,s.split())
 while b<=a:
  need=(a+b-1)//b
  if c<need:break
  c-=need;b+=a//b
 return str(b)
def database(s):
 lines=s.splitlines();a=[];out=[]
 for line in lines[1:]:
  op,*v=line.split();v=list(map(int,v))
  if op=='+':a.insert(v[0],v[1])
  elif op=='-':a.pop(v[0])
  elif op=='*':a[v[0]]=v[1]
  else:out.append(str(a.index(v[0])) if v[0] in a else 'Failed')
 return '\n'.join(out)
def combination(s):
 v=list(map(int,s.split()));return '\n'.join(str(math.comb(b,a)) for a,b in zip(v[1::2],v[2::2]))
def cinema(s):
 v=iter(map(int,s.split()));out=[]
 for _ in range(next(v)):
  m,p,q=next(v),next(v),next(v)
  if m==0 or (q-p-m)*(-m)<=0:out.append('0');continue
  # 反射原理：从对称起点计数所有越过不可触边界的路径。
  total=math.comb(p+q,p);r=p+m
  out.append(str(total-(math.comb(p+q,r) if 0<=r<=p+q else 0)))
 return '\n'.join(out)
def synthesis(s):
 v=iter(s.split());n=int(next(v));cost=[Fraction(next(v))];route=[]
 for i in range(n):
  probs=[Fraction(next(v)) for _ in range(i+1)];options=[((cost[i]+cost[j]+100-(1-p)*cost[i-1] if i else cost[i]+cost[j]+100)/p,j) for j,p in enumerate(probs) if p>0]
  if not options:return 'UNREACHABLE'
  best,j=min(options);cost.append(best);route.append(j)
 value=cost[-1];cents,remainder=divmod(abs(value.numerator)*100,value.denominator)
 if 2*remainder>value.denominator or 2*remainder==value.denominator and cents%2:cents+=1
 price=('-' if value<0 and cents else '')+f'{cents//100}.{cents%100:02d}'
 return ' '.join(map(str,route))+'\n'+price

def defile(s):
 v=list(map(int,s.split()));cards,mana=v[:2];a=v[2:]
 for _ in range(min(cards,mana//2)):
  while a:
   a=[x-1 for x in a];died=0 in a;a=[x for x in a if x>0]
   if not died:break
 return 'YES' if not a else 'NO'
def wide_swap(s):
 v=list(map(int,s.split()));n,k=v[:2];a=v[2:];size=1<<n.bit_length();tree=[(0,-1)]*(size*2)
 for i,x in enumerate(a):tree[size+i]=(x,i)
 for i in range(size-1,0,-1):tree[i]=max(tree[2*i],tree[2*i+1])
 def query(l,r):
  l=max(0,l)+size;r=min(n,r)+size;best=(0,-1)
  while l<r:
   if l&1:best=max(best,tree[l]);l+=1
   if r&1:r-=1;best=max(best,tree[r])
   l//=2;r//=2
  return best
 def available(i):return a[i] and query(i-k+1,i+k)[0]==a[i]
 heap=[-i for i in range(n) if available(i)];heapq.heapify(heap);answer=[0]*n;label=n
 while heap:
  i=-heapq.heappop(heap)
  if not a[i]:continue
  answer[i]=label;label-=1;a[i]=0;at=size+i;tree[at]=(0,-1)
  while at>1:at//=2;tree[at]=max(tree[at*2],tree[at*2+1])
  for l,r in [(i-k+1,i),(i+1,i+k)]:
   value,j=query(l,r)
   if value and available(j):heapq.heappush(heap,-j)
 assert label==0
 return ' '.join(map(str,answer))
SOLVERS=dict(zip(NUMBERS,[luffy,database,combination,cinema,synthesis,defile,wide_swap]))
def selfcheck():
 rng=random.Random(8008);counts=Counter()
 def check(n,s,want):assert SOLVERS[n](s).split()==str(want).split(),(n,s,SOLVERS[n](s),want);counts[str(n)]+=1
 for _ in range(150):
  a,b,c=[rng.randint(1,30) for _ in range(3)];states={(b,c)};q=list(states)
  for power,meat in q:
   for eaten in range(1,meat+1):
    if eaten*power>=a:
     nxt=(power+a//power,meat-eaten)
     if nxt not in states:states.add(nxt);q.append(nxt)
  check(19965,f'{a} {b} {c}',max(x for x,_ in states))
  a=rng.randint(0,30);b=rng.randint(a,40);num=1
  for j in range(a):num=num*(b-j)//(j+1)
  check(19971,f'1\n{a} {b}',num)
  m=rng.randint(-5,5);p=rng.randint(1,10);q=rng.randint(1,10);dp=[[0]*(q+1) for _ in range(p+1)];dp[0][0]=int(m!=0)
  for i in range(p+1):
   for j in range(q+1):
    if i==j==0:continue
    if j!=i+m:dp[i][j]=(dp[i-1][j] if i else 0)+(dp[i][j-1] if j else 0)
  check(19974,f'1\n{m} {p} {q}',dp[p][q])
  cards=rng.randint(0,2);mana=rng.randint(0,10);values=[rng.randint(1,10) for _ in range(14)];present=set(values);missing=sum(x not in present for x in range(1,max(values)+1));check(19998,f'{cards} {mana}\n'+' '.join(map(str,values)),'YES' if missing<min(cards,mana//2) else 'NO')
  n=rng.randint(2,7);k=rng.randint(1,n-1);a=list(range(1,n+1));rng.shuffle(a);start=tuple(a);seen={start};q=deque([start])
  while q:
   row=q.popleft()
   for i in range(n):
    for j in range(i+k,n):
     if abs(row[i]-row[j])==1:
      nxt=list(row);nxt[i],nxt[j]=nxt[j],nxt[i];nxt=tuple(nxt)
      if nxt not in seen:seen.add(nxt);q.append(nxt)
  check(27699,f'{n} {k}\n'+' '.join(map(str,a)),' '.join(map(str,min(seen))))
 for _ in range(150):
  model={};ops=[];out=[]
  for step in range(40):
   op=rng.choice(['+','?']+(['-','*'] if model else []))
   if op=='+':
    i=rng.randint(0,len(model));value=rng.randint(-10,10);ops.append(f'+ {i} {value}');model={j+int(j>=i):x for j,x in model.items()};model[i]=value
   elif op=='-':
    i=rng.randrange(len(model));ops.append(f'- {i}');model={j-int(j>i):x for j,x in model.items() if j!=i}
   elif op=='*':
    i=rng.randrange(len(model));value=rng.randint(-10,10);ops.append(f'* {i} {value}');model[i]=value
   else:
    value=rng.randint(-10,10);ops.append(f'? {value}');found=[j for j,x in model.items() if x==value];out.append(str(min(found)) if found else 'Failed')
  check(19967,str(len(ops))+'\n'+'\n'.join(ops),'\n'.join(out))
  n=rng.randint(1,5);price=rng.randint(1,100);p=[[Fraction(rng.randint(1,100),100) for j in range(i+1)] for i in range(n)];options=[]
  for route in itertools.product(*(range(i+1) for i in range(n))):
   costs=[Fraction(price)]
   for i,j in enumerate(route):costs.append((costs[i]+costs[j]+100-(1-p[i][j])*costs[i-1] if i else costs[i]+costs[j]+100)/p[i][j])
   options.append((costs[-1],route))
  best,route=min(options)
  if sum(x==best for x,r in options)!=1:continue
  with localcontext() as ctx:
   ctx.prec=80;value=Decimal(best.numerator)/Decimal(best.denominator);want=' '.join(map(str,route))+'\n'+format(value.quantize(Decimal('.01'),rounding=ROUND_HALF_EVEN),'.2f')
  given=str(n)+'\n'+str(price)+'\n'+'\n'.join(' '.join(format(Decimal(x.numerator)/Decimal(x.denominator),'.2f') for x in row) for row in p)
  check(19984,given,want)
 check(19967,'6\n+ 0 1\n+ 0 2\n? 2\n* 1 3\n- 1\n? 1','0\nFailed')
 check(19984,'2\n100\n1\n0.8 0.95','0 0\n600.00')
