struct Integer {
 std::vector<uint32_t> d;static const uint64_t B=1000000000;
 Integer(uint64_t x=0){while(x){d.push_back(x%B);x/=B;}}
 void trim(){while(!d.empty()&&d.back()==0)d.pop_back();}
 bool operator<(const Integer& b)const{if(d.size()!=b.d.size())return d.size()<b.d.size();for(size_t i=d.size();i-->0;)if(d[i]!=b.d[i])return d[i]<b.d[i];return false;}
 bool operator==(const Integer&b)const{return d==b.d;}
 bool operator!=(const Integer&b)const{return !(*this==b);}
 bool operator>(const Integer&b)const{return b<*this;}
 bool operator<=(const Integer&b)const{return !(b<*this);}
 bool operator>=(const Integer&b)const{return !(*this<b);}
 Integer&operator+=(const Integer&b){d.resize(std::max(d.size(),b.d.size()),0);uint64_t carry=0;for(size_t i=0;i<d.size();i++){uint64_t x=uint64_t(d[i])+(i<b.d.size()?b.d[i]:0)+carry;d[i]=x%B;carry=x/B;}if(carry)d.push_back(carry);return *this;}
 Integer&operator-=(const Integer&b){if(*this<b)throw std::runtime_error("negative exact integer");int64_t borrow=0;for(size_t i=0;i<d.size();i++){int64_t x=int64_t(d[i])-(i<b.d.size()?b.d[i]:0)-borrow;borrow=x<0;if(borrow)x+=B;d[i]=x;}trim();return *this;}
 Integer operator+(const Integer&b)const{Integer r=*this;r+=b;return r;}
 Integer operator-(const Integer&b)const{Integer r=*this;r-=b;return r;}
 Integer operator*(const Integer&b)const{Integer r;r.d.resize(d.size()+b.d.size()+1);for(size_t i=0;i<d.size();i++){uint64_t carry=0;for(size_t j=0;j<b.d.size()||carry;j++){uint64_t x=r.d[i+j]+carry+(j<b.d.size()?uint64_t(d[i])*b.d[j]:0);r.d[i+j]=x%B;carry=x/B;}}r.trim();return r;}
 template<class T>T convert_to()const{uint64_t r=0;for(size_t i=d.size();i-->0;)r=r*B+d[i];return T(r);}
 friend Integer operator*(int a,const Integer&b){return Integer(a)*b;}
 friend std::istream&operator>>(std::istream&in,Integer&v){std::string s;if(in>>s){v=0;for(char c:s){if(c<'0'||c>'9')throw std::runtime_error("invalid integer");v=v*Integer(10)+Integer(c-'0');}}return in;}
};

