from collections import Counter
from math import comb

def two_sum_stream(given,answer):
 v=list(map(int,given.split()));out=list(map(int,answer.split()));at=0;cases=[];results=[];errors=[]
 while at<len(v):
  n,target=v[at:at+2];at+=2
  if n==target==0:break
  nums=v[at:at+n];at+=n;freq=Counter(nums);pairs=sum(freq[x]*freq[target-x] for x in freq if x<target-x)+sum(comb(freq[x],2) for x in freq if x==target-x)
  cases.append(nums);i=len(cases)-1
  if not(2<=n<=10000 and len(nums)==n and -10**9<=target<=10**9 and all(-10**9<=x<=10**9 for x in nums)):errors.append({'case':i+1,'reason':'函数题长度或数值范围不符'})
  if pairs!=1:errors.append({'case':i+1,'reason':'不满足恰有一个有效答案'})
  if 2*i+2<=len(out):
   a,b=out[2*i:2*i+2];results.append(0<=a<b<n and nums[a]+nums[b]==target)
  else:results.append(False)
 if at!=len(v):errors.append({'reason':'终止标记后仍有token'})
 if len(cases)!=100:errors.append({'reason':'不是题面规定的100组测试'})
 return {'cases':len(cases),'input_issues':errors,'output_indices_valid':len(out)==2*len(cases) and all(results)}

def hal_certificate(given,answer):
