 for i in range(k):
  r,c,t=v[4+3*i:7+3*i]
  if not(1<=r<=n and 1<=c<=m and 1<=t<=n*m-b):issues.append('锁定范围违规')
  if t in locks and locks[t]!=(r,c):issues.append('同一时刻锁定冲突')
  locks[t]=(r,c);locked_cells.add((r,c))
 at=4+3*k;blocked=set(zip(v[at::2],v[at+1::2]));total=n*m-len(blocked)
 if len(blocked)!=b:issues.append('坏死格重复')
 if blocked&locked_cells:issues.append('锁定与坏死格重叠')
 if 1 not in locks:issues.append('未指定起点')
 if not(1<=n<=10 and 1<=m<=10):issues.append('矩阵范围违规')
 tokens=answer.split()
 if tokens==['-1']:return {'input_issues':issues,'kind':'negative_requires_independent_proof','certificate_valid':False}
