"""直接计算给定卡片的排名：前缀约束累计计数与精确整数后缀，不使用参考解的逐项选号及int64排序。"""
from functools import lru_cache
from math import isqrt

def first_counts(n):
 counts=[1]
 for total in range(1,n+1):counts.append(sum(counts[total-d]*sum(d%j==0 for j in range(1,d+1)) for d in range(1,total+1)))
 return counts

def generated(c,a,width):
 seq=list(a);k=len(c)
 for _ in range(width):seq.append(sum(c[j]*seq[-k+j] for j in range(k)))
 return tuple(seq[k:])

@lru_cache(maxsize=300000)
def _ways(rem,prev,upper):
 if rem[0]==0:return int(all(x==0 for x in rem[:-1]) and (rem[-1]>=0 if upper else rem[-1]==0))
 if any(x<=0 for x in rem):return 0
 # 所有较短前缀也必须可满足；先排除不可能的残余前缀，再枚举正系数。
 if len(rem)>1 and not _ways(rem[:-1],prev[:-1],False):return 0
 answer=0
 for coeff in range(1,rem[0]+1):
  for seed in range(1,rem[0]//coeff+1):
   column=(seed,)+prev;nxt=tuple(x-coeff*y for x,y in zip(rem,column))
   if min(nxt)<0:continue
   answer+=_ways(nxt,column[:-1],upper)
 return answer

def counter(prefix,upper=False):
 target=tuple(prefix);history=target[:-1]
 def ways(rem,prev):return _ways(rem,prev,upper)
 return ways,target,history

def candidates(prefix):
 ways,target,history=counter(prefix);answer=[]
 def visit(rem,prev,cs,seeds):
  if rem[0]==0:
   if ways(rem,prev):answer.append((tuple(reversed(cs)),tuple(reversed(seeds))))
   return
  for coeff in range(1,rem[0]+1):
   for seed in range(1,rem[0]//coeff+1):
    column=(seed,)+prev;nxt=tuple(x-coeff*y for x,y in zip(rem,column))
    if min(nxt)>=0 and ways(nxt,column[:-1]):visit(nxt,column[:-1],cs+(coeff,),seeds+(seed,))
 visit(target,history,(),());assert len(answer)==ways(target,history)
 return answer

def exact_rank(c,a):
 _ways.cache_clear();first=generated(c,a,1)[0];assert first<=24
 counts=first_counts(first);before=sum(counts[1:first]);prefix=[];all_generated=generated(c,a,2*first+1);details=[]
 for value in all_generated:
  if prefix:
   ways,target,prev=counter(prefix+[value-1],upper=True);smaller=ways(target,prev);before+=smaller
  else:smaller=sum(counts[1:first])
  prefix.append(value);ways,target,prev=counter(prefix);matching=ways(target,prev);details.append({'prefix_length':len(prefix),'matching_cards':matching,'strictly_smaller_at_this_coordinate':smaller})
  if matching<=100:
   rows=candidates(prefix)
   # 两张卡片阶数之和不超过2*first；差序列满足至多该阶线性递推。
   # 因而前2*first个生成值相同即可证明后缀完全相同，再按系数向量排序。
   rows.sort(key=lambda card:(generated(*card,2*first),card[0]));index=rows.index((tuple(c),tuple(a)))
   return before+index+1,details
 raise AssertionError('完整有理递推前缀仍未降到可枚举规模')

def exhaustive_cards(total):
 rows=[]
 def build(rem,c,a):
  if rem==0:rows.append((c,a));return
  for coeff in range(1,rem+1):
   for seed in range(1,rem//coeff+1):build(rem-coeff*seed,c+(coeff,),a+(seed,))
 build(total,(),());return rows

def selfcheck():
 rows=[]
 for first in range(1,7):rows.extend(exhaustive_cards(first))
 rows.sort(key=lambda card:(generated(*card,12),card[0]))
 for rank,(c,a) in enumerate(rows,1):assert exact_rank(c,a)[0]==rank,(rank,c,a,exact_rank(c,a))
 return len(rows)
if __name__=='__main__':print(selfcheck())

// 直接累计给定递推卡片排名；精确整数后缀，不读取参考程序。
#include <algorithm>
#include <iostream>
#include <map>
#include <tuple>
#include <vector>
#include "gmyhf_rank_integer.hpp"
using namespace std;using Z=Integer;using V=vector<Z>;using U=unsigned long long;
map<tuple<V,V,bool>,U> memo;
U ways(V rem,V prev,bool upper){
 if(rem[0]==0){for(size_t i=1;i+1<rem.size();i++)if(rem[i]!=0)return 0;return rem.size()==1 || (upper? rem.back()>=0:rem.back()==0);}
 for(auto x:rem)if(x<=0)return 0;
 auto key=make_tuple(rem,prev,upper);auto found=memo.find(key);if(found!=memo.end())return found->second;
 if(rem.size()>1){V a(rem.begin(),rem.end()-1),b(prev.begin(),prev.end()-1);if(!ways(a,b,false))return memo[key]=0;}
 U ans=0;int first=rem[0].convert_to<int>();
 for(int c=1;c<=first;c++)for(int a=1;a*c<=first;a++){
  V column{Z(a)};column.insert(column.end(),prev.begin(),prev.end());V next=rem;bool ok=true;
  for(size_t j=0;j<next.size();j++){Z term=c*column[j];if(next[j]<term){ok=false;break;}next[j]-=term;}
  if(!ok)continue;column.pop_back();ans+=ways(next,column,upper);
 }
 return memo[key]=ans;
}
using Card=pair<V,V>;
void enumerate(V rem,V prev,V c,V a,vector<Card>& result){
 if(rem[0]==0){if(ways(rem,prev,false)){reverse(c.begin(),c.end());reverse(a.begin(),a.end());result.push_back({c,a});}return;}
 int first=rem[0].convert_to<int>();
 for(int ci=1;ci<=first;ci++)for(int ai=1;ci*ai<=first;ai++){
  V column{Z(ai)};column.insert(column.end(),prev.begin(),prev.end());V next=rem;bool ok=true;
  for(size_t j=0;j<next.size();j++){Z term=ci*column[j];if(next[j]<term){ok=false;break;}next[j]-=term;}
  if(!ok)continue;column.pop_back();if(!ways(next,column,false))continue;
  V nc=c,na=a;nc.push_back(ci);na.push_back(ai);enumerate(next,column,nc,na,result);
 }
}
V generate(const Card& card,int width){auto [c,a]=card;int k=c.size();for(int t=0;t<width;t++){Z x=0;for(int i=0;i<k;i++)x+=c[i]*a[a.size()-k+i];a.push_back(x);}return V(a.begin()+k,a.end());}
U rank_card(Card card){
 memo.clear();int first=generate(card,1)[0].convert_to<int>();if(first<1||first>24)throw runtime_error("first outside proved rank range");
 vector<U> counts(first+1);counts[0]=1;for(int t=1;t<=first;t++)for(int d=1;d<=t;d++)for(int j=1;j<=d;j++)if(d%j==0)counts[t]+=counts[t-d];
 U before=0;for(int t=1;t<first;t++)before+=counts[t];V prefix,gen=generate(card,2*first+1);
 for(Z value:gen){
  if(!prefix.empty()){V upper=prefix,prev=prefix;upper.push_back(value-1);before+=ways(upper,prev,true);}
  V prev=prefix;prefix.push_back(value);U matching=ways(prefix,prev,false);
  if(matching<=100){vector<Card> cards;enumerate(prefix,prev,{}, {},cards);if(cards.size()!=matching)throw runtime_error("enumeration count mismatch");
   vector<pair<pair<V,V>,Card>> ordered;for(auto x:cards)ordered.push_back({{generate(x,2*first),x.first},x});sort(ordered.begin(),ordered.end());
   for(size_t i=0;i<ordered.size();i++)if(ordered[i].second==card)return before+i+1;throw runtime_error("target missing");}
 }
 throw runtime_error("prefix not sufficient");
}
int main(){int k;while(cin>>k){V c(k),a(k);for(auto&x:c)cin>>x;for(auto&x:a)cin>>x;cout<<rank_card({c,a})<<'\n';}}

